def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Return True if any two distinct elements in `numbers` differ by less 
    than `threshold`; otherwise return False."""
    if threshold < 0:
        return False
    sorted_nums = sorted(numbers)
    for i in range(1, len(sorted_nums)):
        if sorted_nums[i] - sorted_nums[i - 1] < threshold:
            return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from math import inf
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] - maximum sum when path1 is at (i1, j1) and path2 at (i2, j2),
    # where j1 = k - i1, j2 = k - i2, k = current step index (sum of coordinates)
    dp = [[-inf] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # both start at (1,1), collect its value once

    for k in range(3, 2 * N + 1):
        new_dp = [[-inf] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = -inf
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1:
                            continue
                        best = max(best, dp[pi1][pi2])
                if best == -inf:
                    continue
                cell = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell += grid[i2][j2]
                new_dp[i1][i2] = best + cell
        dp = new_dp

    return dp[N][N] if dp[N][N] > -inf else 0

def calculate_scholarship(grades: list[int], leader: str, west: str, papers: int) -> int:
    avg, class_eval = grades
    scholarship = 0
    if avg > 80 and papers >= 1:
        scholarship += 8000
    if avg > 85 and class_eval > 80:
        scholarship += 4000
    if avg > 90:
        scholarship += 2000
    if avg > 85 and west == 'Y':
        scholarship += 1000
    if class_eval > 80 and leader == 'Y':
        scholarship += 850
    return scholarship

def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the 10 characters
    raw = isbn.replace('-', '')
    if len(raw) != 10:
        return "Right"  # invalid format, but spec expects valid input

    # Compute checksum over first 9 digits
    try:
        digits = [int(ch) for ch in raw[:9]]
    except ValueError:
        return "Right"  # invalid digits, but spec expects valid

    total = sum((10 - i) * v for i, v in enumerate(digits, 1))
    expected_value = (11 - total % 11) % 11
    expected_char = 'X' if expected_value == 10 else str(expected_value)

    actual_char = raw[9]
    if actual_char == expected_char:
        return "Right"

    # Construct corrected ISBN preserving hyphen positions
    parts = isbn.split('-')
    parts[-1] = expected_char
    return '-'.join(parts)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from itertools import combinations
    # Precompute pair indices
    pairs = list(chatting_pairs)
    pair_count = len(pairs)
    # Rows to consider are 1..M-1, columns 1..N-1
    possible_rows = list(range(1, M))
    possible_cols = list(range(1, N))
    # For each row, determine which pairs are separated by an aisle at that row
    row_seps = {}
    for r in possible_rows:
        separated = set()
        for idx, (x1, y1, x2, y2) in enumerate(pairs):
            if (x1 - r) * (x2 - r) < 0 or (x1 <= r < x2) or (x2 <= r < x1):
                # Equivalent to x1 <= r < x2 or x2 <= r < x1
                separated.add(idx)
        row_seps[r] = separated
    # For each column
    col_seps = {}
    for c in possible_cols:
        separated = set()
        for idx, (x1, y1, x2, y2) in enumerate(pairs):
            if (y1 - c) * (y2 - c) < 0 or (y1 <= c < y2) or (y2 <= c < y1):
                separated.add(idx)
        col_seps[c] = separated

    # Helper to generate subsets of size k
    def subsets(lst, k):
        if k == 0:
            return [()]
        return combinations(lst, k)

    best_count = -1
    best_row_set = ()
    best_col_set = ()
    # Iterate over all row combinations
    for row_subset in subsets(possible_rows, K):
        row_cover = set()
        for r in row_subset:
            row_cover.update(row_seps[r])
        # For each column combination, evaluate total cover
        for col_subset in subsets(possible_cols, L):
            col_cover = set()
            for c in col_subset:
                col_cover.update(col_seps[c])
            total_cover = row_cover | col_cover
            count = len(total_cover)
            if count > best_count:
                best_count = count
                best_row_set = row_subset
                best_col_set = col_subset

    # Format result
    row_str = ' '.join(str(r) for r in sorted(best_row_set))
    col_str = ' '.join(str(c) for c in sorted(best_col_set))
    return (row_str, col_str)

def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
    unique_numbers = sorted(set(numbers))
    return len(unique_numbers), unique_numbers

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first_term = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue
        sign = ''
        if first_term:
            if coeff < 0:
                sign = '-'
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        coeff_str = ''
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)
        var_part = ''
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        term = f"{sign}{coeff_str}{var_part}"
        terms.append(term)
        first_term = False
    return ''.join(terms) if terms else "0"

def select_volunteers(n: int, m: int, applicants: list) -> tuple:
    sorted_app = sorted(applicants, key=lambda x: (-x[1], x[0]))
    cutoff_index = int(1.5 * m)  # floor by default for positive numbers
    if cutoff_index <= 0:
        cutoff_score = 0
    else:
        if cutoff_index > len(sorted_app):
            cutoff_index = len(sorted_app)
        cutoff_score = sorted_app[cutoff_index - 1][1]
    qualified = [app for app in sorted_app if app[1] >= cutoff_score]
    return cutoff_score, qualified

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) != 26:
        return "Failed"
    # Decode the message
    try:
        return ''.join(mapping[ch] for ch in message)
    except KeyError:
        return "Failed"

def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of the product of two distinct primes."""
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0
    k = y0 // x0
    ans = 0
    import math
    limit = int(math.isqrt(k))
    for a in range(1, limit + 1):
        if k % a == 0:
            b = k // a
            if math.gcd(a, b) == 1:
                if a == b:
                    ans += 1
                else:
                    ans += 2
    return ans

def preorder_traversal(inorder: str, postorder: str) -> str:
    idx_map = {c: i for i, c in enumerate(inorder)}

    def build(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l > in_r:
            return ''
        root = postorder[post_r]
        root_idx = idx_map[root]
        left_count = root_idx - in_l
        left = build(in_l, root_idx - 1, post_l, post_l + left_count - 1)
        right = build(root_idx + 1, in_r, post_l + left_count, post_r - 1)
        return root + left + right

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    visited = {A}
    queue = deque([(A, 0)])
    max_steps = 10

    while queue:
        current, steps = queue.popleft()
        if current == B:
            return steps
        if steps >= max_steps:
            continue
        for src, dst in rules:
            if not src:
                continue  # skip invalid rule with empty source
            idx = 0
            while True:
                pos = current.find(src, idx)
                if pos == -1:
                    break
                new_str = current[:pos] + dst + current[pos + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                idx = pos + 1  # allow overlapping matches
    return "NO ANSWER!"

def generate_numbers(n: int, rules) -> int:
    from collections import deque
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(x, []).append(y)

    visited = {n}
    queue = deque([n])

    while queue:
        cur_num = queue.popleft()
        cur_str = str(cur_num)
        for i, ch in enumerate(cur_str):
            digit = int(ch)
            if digit in rule_map:
                for y in rule_map[digit]:
                    new_str = cur_str[:i] + str(y) + cur_str[i+1:]
                    new_num = int(new_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    day_set = {day.upper() for day in days_of_week}

    # Helper to determine truth of a statement
    def is_truth(stmt: str, speaker: str) -> bool:
        # Remove period and normalize whitespace
        cleaned = stmt.strip().replace('.', '').upper()
        # Early skip if the statement refers to a day of the week
        if any(day in cleaned for day in day_set):
            return None  # ignore this statement

        # Parse statements of the form "I am guilty" / "I am not guilty"
        if cleaned.startswith("I AM"):
            if cleaned == "I AM GUILTY":
                return scenario == speaker
            if cleaned == "I AM NOT GUILTY":
                return scenario != speaker
            return None

        # Parse statements like "NAME is guilty" / "NAME is not guilty"
        parts = cleaned.split()
        if len(parts) >= 3 and parts[1] == "IS":
            target_name = parts[0]
            if parts[2] == "GUILTY":
                return scenario == target_name
            if parts[2] == "NOT" and len(parts) >= 4 and parts[3] == "GUILTY":
                return scenario != target_name
        return None  # unrecognized statement types are ignored

    for speaker, stmts in statements.items():
        speaker = speaker.upper()
        for stmt in stmts:
            truth_val = is_truth(stmt, speaker)
            if truth_val is None:  # statement ignored (due to day or unrecognized)
                continue
            if speaker in liar_set:
                if truth_val:      # liar can't tell a true statement
                    return False
            else:
                if not truth_val:   # truth-teller can't tell a false statement
                    return False
    return True

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]

def count_apples_reachable(apple_heights: List[int], tao_reach: int) -> int:
    max_reach = tao_reach + 30
    count = 0
    for height in apple_heights:
        if height <= max_reach:
            count += 1
    return count

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return dp[T]

def find_most_unhappy_day(schedule) -> int:
    max_diff = 0
    best_day = 0
    for day, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            diff = total - 8
            if diff > max_diff:
                max_diff = diff
                best_day = day
    return best_day

def minimum_students_to_leave(heights):
    """
    Compute the minimum number of students that need to be removed
    so that the remaining heights form a bitonic sequence:
    strictly increasing up to some peak and then strictly decreasing.
    """
    n = len(heights)
    if n <= 2:
        return 0  # already a valid bitonic sequence

    # LIS: longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # LDS: longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        # subtract 1 to avoid counting the peak twice
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new = butts // k
        total += new
        butts = butts % k + new
    return total
